optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/identity.rs b/tools/bot-evaluation/src/identity.rs
index 1861494b..f2078e57 100644
--- a/tools/bot-evaluation/src/identity.rs
+++ b/tools/bot-evaluation/src/identity.rs
@@ -90,16 +90,27 @@ struct Evidence<T: Serialize> {
     encoding_version: &'static str,
     evidence: T,
 }
+fn hash_serialized(value: &impl Serialize) -> String {
+    struct Sink(Sha256);
+    impl std::io::Write for Sink {
+        fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> { self.0.update(bytes); Ok(bytes.len()) }
+        fn flush(&mut self) -> std::io::Result<()> { Ok(()) }
+    }
+    let mut writer = std::io::BufWriter::with_capacity(16384, Sink(Sha256::new()));
+    serde_json::to_writer(&mut writer, value).unwrap();
+    use std::io::Write;
+    writer.flush().unwrap();
+    format!("{:x}", writer.into_inner().map_err(|_| ()).unwrap().0.finalize())
+}
 pub fn digest(value: &Value) -> String {
-    sha(serde_json::to_vec(&Canonical(value, false)).unwrap())
+    hash_serialized(&Canonical(value, false))
 }
 #[cfg(test)]
 pub fn evidence(value: &Value) -> String {
-    sha(serde_json::to_vec(&Evidence {
+    hash_serialized(&Evidence {
         encoding_version: "1",
         evidence: Canonical(value, true),
     })
-    .unwrap())
 }
 pub fn game_evidence(
     game_id: &Value,
@@ -114,7 +125,7 @@ pub fn game_evidence(
         game_id: Canonical<'a>,
         records: [Canonical<'a>; 2],
     }
-    sha(serde_json::to_vec(&Evidence {
+    hash_serialized(&Evidence {
         encoding_version: "1",
         evidence: Game {
             configurations: configurations.map(|v| Canonical(v, true)),
@@ -123,7 +134,6 @@ pub fn game_evidence(
             records: records.map(|v| Canonical(v, true)),
         },
     })
-    .unwrap())
 }

 #[cfg(test)]
